/**
 * The payment channel. v1 implements BOOK_TRANSFER, FPS (Malai-to-Malai
 * and to non-Malai UK destinations), and SWIFT (international, stubbed)
 * outbound end-to-end. BACS_DIRECT_CREDIT is reserved for the inbound
 * ambient-activity slice.
 *
 */
export const zRail = z.enum([
  "BOOK_TRANSFER",
  "FPS",
  "SWIFT",
  "BACS_DIRECT_CREDIT",
]);

/**
 * Lifecycle state for a Payment.
 * - `BOOK_TRANSFER` payments are born `SETTLED` (no `PENDING` window).
 * - `FPS` payments are born `PENDING`. The Stub FPS scheme settles them
 * within ~1 simulated second, after which `GET /api/v1/payments/{id}`
 * returns `state = SETTLED`. Returns move `PENDING → RETURNED` and
 * carry a `returnReason`.
 * - `SWIFT` payments are born `PENDING` and always settle (no return
 * path in v1) after a configurable simulated delay (~30s in real
 * deployments; 0s in tests).
 * - `REFERRED` means pre-dispatch screening flagged the payment and the
 * bank has parked it for review. The payer's funds stay reserved and
 * nothing has been sent to the scheme. A referred payment moves to
 * `PENDING` (released, then the normal rail path) or `DECLINED`.
 * - `DECLINED` is terminal: the bank refused the payment before it
 * reached the scheme, the reservation on the payer's funds is
 * released, and nothing was posted.
 *
 * Deliberately no field explains *why* a payment is `REFERRED` or
 * `DECLINED`. A bank must not tip off a suspected fraudster, so the
 * customer-facing contract carries the state and nothing more.
 *
 */
export const zPaymentState = z.enum([
  "PENDING",
  "SETTLED",
  "RETURNED",
  "REFERRED",
  "DECLINED",
]);

/**
 * Why an FPS-routed payment was returned by the scheme. Set on the
 * `Payment` row when the lifecycle moves `PENDING → RETURNED` and
 * surfaced on `GET /api/v1/payments/{id}`.
 *
 */
export const zReturnReason = z.enum([
  "ACCOUNT_CLOSED",
  "ACCOUNT_NAME_MISMATCH",
  "RECIPIENT_BANK_UNAVAILABLE",
  "BENEFICIARY_DECEASED",
  "INVALID_ACCOUNT",
]);

/**
 * Deterministic outcome the demo stub will produce when a payment is
 * sent to this counterparty. `SETTLES` → the canonical happy path.
 * `RETURNS` → the payment will be returned by the simulated scheme
 * with the row's `returnReason`. `STUCK_PENDING` → the payment will
 * stay `PENDING` indefinitely (cleared by `demo-reset.sh`).
 *
 */
export const zOutboundOutcome = z.enum(["SETTLES", "RETURNS", "STUCK_PENDING"]);

